<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Personal Expense Tracker</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;max-width:800px;margin:2rem auto;padding:0 1rem}
h1{font-size:1.5rem}
label{display:block;margin:.5rem 0}
input,select,button{font:inherit;padding:.4rem;margin-top:.2rem}
#expense-form,#filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.5rem;margin:1rem 0}
#form-error{color:#b00020;margin:.5rem 0}
#summary{margin:1rem 0;padding:.5rem;border-top:1px solid #ddd}
.cat-total{margin:.2rem 0}
.expense{display:flex;gap:1rem;align-items:center;padding:.4rem;border-bottom:1px solid #eee}
.expense .exp-amount{font-weight:600;min-width:80px}
.expense .exp-cat{min-width:100px;text-transform:capitalize}
.expense .exp-date{min-width:120px}
.exp-del{background:#eee;border:1px solid #ccc;cursor:pointer}
.exp-del:hover{background:#fdd}
#expense-list{margin-top:1rem}
</style>
</head>
<body>
<h1>Personal Expense Tracker</h1>

<div id="form-error" role="alert"></div>

<form id="expense-form" novalidate>
<label>Amount <input id="amount" type="number" step="0.01" min="0" required></label>
<label>Category
<select id="category">
<option value="groceries">groceries</option>
<option value="transport">transport</option>
<option value="bills">bills</option>
<option value="fun">fun</option>
</select>
</label>
<label>Date <input id="date" type="date" required></label>
<label>Note <input id="note" type="text" placeholder="optional"></label>
<button id="add-expense" type="submit">Add Expense</button>
</form>

<div id="filters">
<label>Category
<select id="filter-category">
<option value="all">all</option>
<option value="groceries">groceries</option>
<option value="transport">transport</option>
<option value="bills">bills</option>
<option value="fun">fun</option>
</select>
</label>
<label>From <input id="filter-from" type="date"></label>
<label>To <input id="filter-to" type="date"></label>
</div>

<div id="summary">
<div>Total visible: <strong><span id="total">0.00</span></strong></div>
<div id="cat-summary">
<div class="cat-total" data-cat="groceries">groceries: 0.00</div>
<div class="cat-total" data-cat="transport">transport: 0.00</div>
<div class="cat-total" data-cat="bills">bills: 0.00</div>
<div class="cat-total" data-cat="fun">fun: 0.00</div>
</div>
</div>

<div id="expense-list"></div>

<script>
(() => {
const STORAGE_KEY = 'personal_expenses_v1';
const categories = ['groceries','transport','bills','fun'];

function escapeHtml(s){return s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function loadExpenses(){try{const raw=localStorage.getItem(STORAGE_KEY);return raw?JSON.parse(raw):[]}catch{return []}}
function saveExpenses(){localStorage.setItem(STORAGE_KEY,JSON.stringify(expenses));}

let expenses = loadExpenses();

const listEl = document.getElementById('expense-list');
const totalEl = document.getElementById('total');
const errorEl = document.getElementById('form-error');

function render(){
  listEl.innerHTML='';
  const sorted=[...expenses].sort((a,b)=>{if(a.date!==b.date)return b.date.localeCompare(a.date);return b.id-a.id;});
  sorted.forEach(e=>{
    const row=document.createElement('div');
    row.className='expense';
    row.dataset.id=e.id;
    row.dataset.cat=e.category;
    row.dataset.date=e.date;
    row.dataset.amount=e.amount;
    row.innerHTML=`
      <span class="exp-amount">$${Number(e.amount).toFixed(2)}</span>
      <span class="exp-cat">${e.category}</span>
      <span class="exp-date">${e.date}</span>
      <button class="exp-del" aria-label="Delete">✕</button>`;
    listEl.appendChild(row);
  });
  applyFilters();
}

function applyFilters(){
  const catFilter=document.getElementById('filter-category').value;
  const from=document.getElementById('filter-from').value;
  const to=document.getElementById('filter-to').value;
  let total=0;
  const catSums={};
  categories.forEach(c=>catSums[c]=0);
  document.querySelectorAll('.expense').forEach(row=>{
    const rowCat=row.dataset.cat;
    const rowDate=row.dataset.date;
    const amount=parseFloat(row.dataset.amount);
    let visible=true;
    if(catFilter!=='all' && rowCat!==catFilter) visible=false;
    if(from && rowDate<from) visible=false;
    if(to && rowDate>to) visible=false;
    if(visible){
      row.style.display='';
      total+=amount;
      catSums[rowCat]=(catSums[rowCat]||0)+amount;
    }else{
      row.style.display='none';
    }
  });
  totalEl.textContent=total.toFixed(2);
  categories.forEach(c=>{
    const el=document.querySelector(`.cat-total[data-cat="${c}"]`);
    if(el) el.textContent=`${c}: ${(catSums[c]||0).toFixed(2)}`;
  });
}

document.getElementById('expense-form').addEventListener('submit',e=>{
  e.preventDefault();
  const amountInput=document.getElementById('amount');
  const dateInput=document.getElementById('date');
  const categoryInput=document.getElementById('category');
  const noteInput=document.getElementById('note');
  const amountVal=amountInput.value.trim();
  const amount=parseFloat(amountVal);
  const dateVal=dateInput.value;
  if(!amountVal || isNaN(amount) || amount<=0 || !dateVal){
    errorEl.textContent='Amount must be greater than zero and date is required.';
    return;
  }
  errorEl.textContent='';
  const expense={
    id:Date.now()+Math.random(),
    amount,
    category:categoryInput.value,
    date:dateVal,
    note:noteInput.value.trim()
  };
  expenses.push(expense);
  saveExpenses();
  amountInput.value='';
  render();
});

listEl.addEventListener('click',e=>{
  if(e.target.classList.contains('exp-del')){
    const row=e.target.closest('.expense');
    const id=Number(row.dataset.id);
    expenses=expenses.filter(exp=>exp.id!==id);
    saveExpenses();
    render();
  }
});

['filter-category','filter-from','filter-to'].forEach(id=>{
  const el=document.getElementById(id);
  el.addEventListener('change',applyFilters);
  el.addEventListener('input',applyFilters);
});

render();
})();
</script>
</body>
</html>
